Cho hình vẽ 

a) Kể tên các góc bằng nhau có trong hình.

b) Cho  $\widehat { G_{4} }= \widehat{ H_{4} }=55^{\circ}$ tính số đo các góc còn lại.
}{
\begin{tikzpicture}
            \coordinate (E) at (1.14, 3.06);
            \coordinate (D) at (4.46, 0);
            \coordinate (C) at (-0.6, 0);
            \coordinate (B) at (5, 2);
            \coordinate (A) at (0, 2);
            \coordinate (F) at (3.6, -1.44);
            \coordinate (H) at (2.81, 0);
            \coordinate (G) at (1.72, 2);
            % Vẽ tứ giác
            \draw[thick] (C) -- (H)--(D);
            \draw[thick] (A) -- (G) -- (B);
            \draw[thick] (E) -- (G) -- (H)--(F);
            % Ghi nhãn các điểm

            \node[above] at (G) {$G$};
            \node[above ] at (H){$H$};
            \draw 
            (G) pic[draw,angle radius = 8] {angle = E--G--A} node[shift={(-25:15pt)}]{$1$}  ;
            \draw (G) node[shift={(30:11pt)}]{$2$};
            \draw  (G) node[shift={(50:-15pt)}]{$3$}  ;
            \draw (G)  node[shift={(-25:-15pt)}]{$4$};  
            \draw (H) pic[draw,angle radius = 10] {angle = E--H--C};
            \draw (H) node[shift={(-25:15pt)}]{$1$};
            \draw (H) node[shift={(40:15pt)}]{$2$}  ;
            \draw  (H) node[shift={(50:-13pt)}]{$3$} ;
            \draw (H) node[shift={(-25:-15pt)}]{$4$}  ;     
        \end{tikzpicture}
}
\loigiai{
$\widehat { G_{4} }=\widehat{ H_{1} }=\widehat{ G_{1} }= \widehat{ H_{4} }=55^{\circ}$\\
$\widehat { G_{2} }= \widehat{ H_{3} }=\widehat{ G_{3} }=\widehat{  H_{2} }=125^{\circ}$
}\end{ex}

